import{At as e,mt as t,n,pt as r}from"./chunks/framework.BrKcMR_c.js";var i=JSON.parse(`{"title":"ADR-0040: Single-source release identity","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0040-single-source-release-identity.md","filePath":"adrs/0040-single-source-release-identity.md","lastUpdated":1789092097000}`),a={name:`adrs/0040-single-source-release-identity.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0040-single-source-release-identity" tabindex="-1">ADR-0040: Single-source release identity <a class="header-anchor" href="#adr-0040-single-source-release-identity" aria-label="Permalink to “ADR-0040: Single-source release identity”">​</a></h1><p>Status: Accepted (implemented 2026-09-08)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The first public release must read <code>0.1 (Kid)</code>. Existing tooling uses canonical <code>0.1.0</code>, but version, codename, build and display strings are managed independently. Release tags can override the source version without agreement checks, and build numbers do not currently increment in CI as documented.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Use one checked-in release record for canonical semantic version, codename and candidate build. Derive Xcode settings, UI labels and release artifacts from it. Display a zero-patch release as <code>major.minor (Codename)</code> while retaining the canonical three-component version for bundles, tags and filenames. Preserve nonzero patch components. Keep version identity independent of presentation mode.</p><p>Validate source, tag, built bundle and packaged app before creating release assets. Candidate builds advance monotonically; public versions advance only for an intentional release. Development/candidate qualifiers distinguish unpublished builds. The implementation and acceptance sequence is in <a href="/VERSIONING">VERSIONING.md</a>.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>The public first-release label is <code>0.1 (Kid)</code>, with canonical <code>0.1.0</code> and tag <code>v0.1.0</code>. A mismatch fails explicitly instead of falling back to stale values. One metadata edit replaces several independent edits, and packaging validates the actual artifact.</p><p>Implemented by the release record, metadata validator, XcodeGen include, bundle/DMG checks and tagged draft workflow. Local candidates carry a source fingerprint and explicit channel. Candidate progression checks use source history and, for distributed artifacts, saved release manifests; source history alone does not prove which builds were shared. Public release acceptance remains separate. This refines ADR-0018 without rewriting its historical decision.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>Changing all machine versions and tags to two components would abandon the existing semantic-version convention unnecessarily. Keeping separate marketing labels in each UI makes drift likely. Deriving release numbers from milestone or commit counts would change product identity for reasons unrelated to a release.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};